(()=>{if((window.scc??(window.scc={})).contact)return;window.scc.contact=!0;const o=document.querySelector(".contact-card");if(!o)return;const n={"contact-nom":"Nom…","contact-prenom":"Prénom…","contact-email":"Email…","contact-message":"Votre message…"},r=new Set(["","Example Text"]);for(const[e,i]of Object.entries(n)){const c=o.querySelector(`#${e}`);c&&r.has(c.getAttribute("placeholder")??"")&&c.setAttribute("placeholder",i)}const t=o.querySelector("#contact-objet");if(!t)return;const a=new Set(["Select one...","First choice","Second choice","Third choice"]);if([...t.options].some(({text:e})=>!a.has(e.trim())))return;const s=["Question générale","Objet perdu ou trouvé","Enseignes et commerces","Événements et animations","Location d'emplacement","Autre"];t.replaceChildren(new Option("Sélectionner un objet",""));for(const e of s)t.append(new Option(e,e))})();
